def funktio(x):
    return x ** 2

def puolisuunnikasmenetelma(a, b, n):
    h = (b - a) / n
    summa = (funktio(a) + funktio(b)) / 2
    for i in range(1, n):
        x = a + i * h
        summa += funktio(x)
    return summa * h

